<?php
declare(strict_types=1);

$apiRoute = trim((string)($_GET['api'] ?? ''), '/');
if ($apiRoute !== '') {
if (session_status() === PHP_SESSION_NONE) {
    session_start([
        'cookie_httponly' => true,
        'cookie_secure' => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off',
        'cookie_samesite' => 'Lax',
    ]);
}

function app_config(): array
{
    static $config;
    if ($config !== null) {
        return $config;
    }

    $config = [];
    $docRoot = $_SERVER['DOCUMENT_ROOT'] ?? '';
    $cwd = getcwd() ?: '';
    $paths = array_unique(array_filter([
        __DIR__ . '/config.php',
        dirname(__DIR__) . '/config.php',
        dirname(dirname(__DIR__)) . '/config.php',
        $cwd . '/config.php',
        $docRoot ? $docRoot . '/config.php' : '',
    ]));

    foreach ($paths as $path) {
        if (is_file($path)) {
            $loaded = @include $path;
            if (is_array($loaded)) {
                $config = $loaded;
                break;
            }
        }
    }
    return $config;
}

function get_config(string $name, ?string $default = null): ?string
{
    $config = app_config();
    if (isset($config[$name]) && $config[$name] !== '') {
        return (string)$config[$name];
    }
    $val = getenv($name);
    if ($val !== false && $val !== '') {
        return (string)$val;
    }
    if (isset($_ENV[$name]) && $_ENV[$name] !== '') {
        return (string)$_ENV[$name];
    }
    if (isset($_SERVER[$name]) && $_SERVER[$name] !== '') {
        return (string)$_SERVER[$name];
    }
    return $default;
}

function auto_detect_app_url(): string
{
    $custom = get_config('APP_URL');
    if ($custom) {
        return $custom;
    }
    $isHttps = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
        || (isset($_SERVER['SERVER_PORT']) && $_SERVER['SERVER_PORT'] == 443)
        || (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https');
    $protocol = $isHttps ? 'https' : 'http';
    $host = $_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? 'localhost';
    $script = $_SERVER['SCRIPT_NAME'] ?? '/index.php';
    return "{$protocol}://{$host}{$script}";
}

function auto_detect_redirect_uri(): string
{
    $custom = get_config('GOOGLE_OAUTH_REDIRECT_URI');
    if ($custom) {
        return $custom;
    }
    $appUrl = auto_detect_app_url();
    if (strpos($appUrl, '.php') !== false) {
        return $appUrl . '?api=google/callback.php';
    }
    $isHttps = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
        || (isset($_SERVER['SERVER_PORT']) && $_SERVER['SERVER_PORT'] == 443)
        || (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https');
    $protocol = $isHttps ? 'https' : 'http';
    $host = $_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? 'localhost';
    return "{$protocol}://{$host}/api/google/callback.php";
}

function env_required(string $name): string
{
    $value = get_config($name);
    if (!$value) {
        json_response([
            'error' => [
                'message' => "Missing server configuration: {$name}. Please set it in config.php on the server."
            ]
        ], 503);
    }
    return $value;
}

function json_response(array $payload, int $status = 200)
{
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    echo json_encode($payload);
    exit;
}

function google_request(string $url, string $method = 'GET', ?string $token = null, ?array $body = null): array
{
    if (!function_exists('curl_init')) {
        throw new RuntimeException('PHP cURL extension is not enabled on this host.');
    }

    $headers = ['Accept: application/json'];
    if ($token) {
        $headers[] = 'Authorization: Bearer ' . $token;
    }
    if ($body !== null) {
        $headers[] = 'Content-Type: application/json';
    }

    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_TIMEOUT => 30,
        CURLOPT_POSTFIELDS => $body === null ? null : json_encode($body),
    ]);
    $raw = curl_exec($ch);
    $status = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $error = curl_error($ch);
    curl_close($ch);

    if ($raw === false) {
        throw new RuntimeException("Google request failed: {$error}");
    }
    $data = json_decode($raw, true);
    if (!is_array($data)) {
        throw new RuntimeException('Google returned an invalid response.');
    }
    if ($status >= 400) {
        $message = $data['error']['message'] ?? "Google returned HTTP {$status}.";
        throw new RuntimeException($message, $status);
    }
    return $data;
}

function require_google_session(): array
{
    if (empty($_SESSION['google'])) {
        json_response(['error' => 'Google account is not connected.'], 401);
    }
    return $_SESSION['google'];
}

function mask_google_key(string $key): string
{
    return strlen($key) > 8 ? substr($key, 0, 4) . '...' . substr($key, -4) : '****';
}

if ($apiRoute === 'generate.php') {
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    echo json_encode(['error' => ['message' => 'POST required.']]);
    exit;
}

$apiKey = env_required('GUEST_GEMINI_API_KEY');
if (!$apiKey) {
    http_response_code(500);
    echo json_encode(['error' => ['message' => 'Guest Gemini service is not configured.']]);
    exit;
}

$payload = json_decode(file_get_contents('php://input'), true);
$prompt = is_array($payload) ? trim((string)($payload['prompt'] ?? '')) : '';

if ($prompt === '' || strlen($prompt) > 20000) {
    http_response_code(400);
    echo json_encode(['error' => ['message' => 'Prompt is required and must be 20,000 characters or less.']]);
    exit;
}

$ch = curl_init(
    'https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=' .
    rawurlencode($apiKey)
);
curl_setopt_array($ch, [
    CURLOPT_POST => true,
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
    CURLOPT_POSTFIELDS => json_encode([
        'contents' => [['parts' => [['text' => $prompt]]]],
        'generationConfig' => [
            'temperature' => 0.2,
            'maxOutputTokens' => 2500,
        ],
    ]),
    CURLOPT_TIMEOUT => 90,
]);

$response = curl_exec($ch);
$status = curl_getinfo($ch, CURLINFO_HTTP_CODE);
$error = curl_error($ch);
curl_close($ch);

if ($response === false) {
    http_response_code(502);
    echo json_encode(['error' => ['message' => 'Guest Gemini request failed: ' . $error]]);
    exit;
}

http_response_code($status >= 400 ? $status : 200);
echo $response;
}
elseif ($apiRoute === 'google/login.php') {
$clientId = get_config('GOOGLE_OAUTH_CLIENT_ID');
$redirectUri = auto_detect_redirect_uri();
$appUrl = auto_detect_app_url();

if (!$clientId) {
    http_response_code(200);
    header('Content-Type: text/html; charset=utf-8');
    echo '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Google OAuth Setup</title><style>*{box-sizing:border-box;}body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#0f172a;color:#f8fafc;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;padding:20px;}.card{background:#1e293b;border:1px solid #334155;border-radius:16px;padding:32px;max-width:560px;width:100%;box-shadow:0 10px 25px -5px rgba(0,0,0,0.5);}h2{color:#38bdf8;margin-top:0;font-size:1.4rem;}p{font-size:0.9rem;color:#94a3b8;line-height:1.6;}code{background:#090d16;color:#38bdf8;padding:3px 6px;border-radius:6px;font-size:0.85rem;}pre{background:#090d16;border:1px solid #334155;padding:16px;border-radius:10px;font-size:0.8rem;color:#e2e8f0;overflow-x:auto;line-height:1.5;}.btn{display:inline-block;background:#0284c7;color:#fff;text-decoration:none;padding:10px 20px;border-radius:8px;font-weight:600;font-size:0.9rem;margin-top:16px;}.btn:hover{background:#0369a1;}</style></head><body><div class="card"><h2>Google OAuth Configuration Required</h2><p>Google Account tethering requires OAuth credentials. Place a <code>config.php</code> file in the same folder as your <code>index.php</code>:</p><pre>&lt;?php
return [
    \'GOOGLE_OAUTH_CLIENT_ID\' => \'your-client-id.apps.googleusercontent.com\',
    \'GOOGLE_OAUTH_CLIENT_SECRET\' => \'your-client-secret\',
    \'GOOGLE_CLOUD_PROJECT_ID\' => \'your-gcp-project-id\',
    \'GUEST_GEMINI_API_KEY\' => \'your-gemini-key\',
];</pre><p>In Google Cloud Console, add this exact redirect URI under <b>Authorized redirect URIs</b>:<br><br><code>' . htmlspecialchars($redirectUri) . '</code></p><a class="btn" href="' . htmlspecialchars($appUrl) . '">&larr; Return to Builder</a></div></body></html>';
    exit;
}

$state = bin2hex(random_bytes(32));
$_SESSION['oauth_state'] = $state;

$query = http_build_query([
    'client_id' => $clientId,
    'redirect_uri' => $redirectUri,
    'response_type' => 'code',
    'scope' => 'openid email profile https://www.googleapis.com/auth/cloud-platform',
    'access_type' => 'offline',
    'prompt' => 'select_account',
    'state' => $state,
]);

header('Location: https://accounts.google.com/o/oauth2/v2/auth?' . $query, true, 302);
exit;
}
elseif ($apiRoute === 'google/callback.php') {
$state = (string)($_GET['state'] ?? '');
if (!$state || !hash_equals((string)($_SESSION['oauth_state'] ?? ''), $state)) {
    json_response(['error' => 'Invalid OAuth state.'], 400);
}
unset($_SESSION['oauth_state']);

$code = (string)($_GET['code'] ?? '');
if (!$code) {
    json_response(['error' => 'Google authorization was not completed.'], 400);
}

$token = google_request('https://oauth2.googleapis.com/token', 'POST', null, [
    'code' => $code,
    'client_id' => env_required('GOOGLE_OAUTH_CLIENT_ID'),
    'client_secret' => env_required('GOOGLE_OAUTH_CLIENT_SECRET'),
    'redirect_uri' => env_required('GOOGLE_OAUTH_REDIRECT_URI'),
    'grant_type' => 'authorization_code',
]);

$profile = google_request('https://openidconnect.googleapis.com/v1/userinfo', 'GET', $token['access_token']);
$_SESSION['google'] = [
    'id' => (string)$profile['sub'],
    'email' => (string)($profile['email'] ?? ''),
    'name' => (string)($profile['name'] ?? ''),
    'avatarUrl' => (string)($profile['picture'] ?? ''),
    'access_token' => (string)$token['access_token'],
    'refresh_token' => (string)($token['refresh_token'] ?? ''),
    'expires_at' => time() + (int)($token['expires_in'] ?? 3600),
];

header('Location: ' . env_required('APP_URL'), true, 302);
exit;
}
elseif ($apiRoute === 'google/session.php') {
if (empty($_SESSION['google'])) {
    json_response(['authenticated' => false]);
}
$google = $_SESSION['google'];
json_response([
    'authenticated' => true,
    'user' => [
        'id' => $google['id'],
        'email' => $google['email'],
        'name' => $google['name'],
        'avatarUrl' => $google['avatarUrl'],
        'tetheredAt' => 0,
    ],
]);
}
elseif ($apiRoute === 'google/logout.php') {
$_SESSION = [];
session_destroy();
json_response(['ok' => true]);
}
elseif ($apiRoute === 'google/keys.php') {
$google = require_google_session();
$project = env_required('GOOGLE_CLOUD_PROJECT_ID');
$data = google_request(
    'https://apikeys.googleapis.com/v2/projects/' . rawurlencode($project) . '/locations/global/keys',
    'GET',
    $google['access_token']
);

$keys = [];
foreach (($data['keys'] ?? []) as $key) {
    $keys[] = [
        'name' => $key['name'] ?? '',
        'displayName' => $key['displayName'] ?? '',
        'uid' => $key['uid'] ?? '',
        'createTime' => $key['createTime'] ?? '',
        'state' => $key['state'] ?? '',
        'keyString' => isset($key['keyString']) ? mask_google_key($key['keyString']) : null,
    ];
}
json_response(['keys' => $keys]);
}
elseif ($apiRoute === 'google/keys-create.php') {
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    json_response(['error' => 'POST required.'], 405);
}
$google = require_google_session();
$body = json_decode(file_get_contents('php://input'), true);
$displayName = trim((string)($body['displayName'] ?? 'nlbasic key'));
if ($displayName === '' || strlen($displayName) > 100) {
    json_response(['error' => 'A display name between 1 and 100 characters is required.'], 400);
}

$project = env_required('GOOGLE_CLOUD_PROJECT_ID');
$operation = google_request(
    'https://apikeys.googleapis.com/v2/projects/' . rawurlencode($project) . '/locations/global/keys',
    'POST',
    $google['access_token'],
    ['displayName' => $displayName]
);
json_response(['operation' => $operation], 202);
}
    exit;
}
